    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        int coins = 0;
        int expense = 0;
        for (int i = 0; i < n; i++) {
            int p;
            scanf("%d", &p);
            if (p < 500) {
                coins++;
                expense += p;
            }
        }
        printf("%d %d\n", coins, expense);
    }
    return 0;
}

