import sys

def solve(data: str) -> str:
    it = iter(data.strip().split())
    out = []

    while True:
        try:
            n = int(next(it))
        except StopIteration:
            break

        if n == 0:
            break

        prices = [int(next(it)) for _ in range(n)]

        # dp[c] = minimum total payment to obtain exactly c coins so far
        INF = 10**18
        dp = [INF] * (n + 1)
        dp[0] = 0

        for x in prices:
            ndp = [INF] * (n + 1)
            for c in range(n + 1):
                if dp[c] == INF:
                    continue

                # Pay exact amount: no new 500-yen coin obtained
                if dp[c] + x < ndp[c]:
                    ndp[c] = dp[c] + x

                # Pay with one 1000-yen bill when possible:
                # receive one 500-yen coin iff change is at least 500, i.e. x <= 500
                if x <= 500 and c + 1 <= n:
                    if dp[c] + 1000 < ndp[c + 1]:
                        ndp[c + 1] = dp[c] + 1000

            dp = ndp

        max_coins = 0
        min_cost = 0
        for c in range(n, -1, -1):
            if dp[c] < INF:
                max_coins = c
                min_cost = dp[c]
                break

        out.append(f"{max_coins} {min_cost}")

    return "\n".join(out)

