import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            int n;
            try {
                n = fs.nextInt();
            } catch (Exception e) {
                break;
            }
            if (n == 0) break;

            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = fs.nextInt();

            // dp[c][r] = minimum total spending to get c coins and end with remainder r (mod 1000)
            long INF = Long.MAX_VALUE / 4;
            long[][] dp = new long[n + 1][1000];
            for (int i = 0; i <= n; i++) Arrays.fill(dp[i], INF);
            dp[0][0] = 0;

            for (int price : a) {
                long[][] ndp = new long[n + 1][1000];
                for (int i = 0; i <= n; i++) Arrays.fill(ndp[i], INF);

                for (int c = 0; c <= n; c++) {
                    for (int r = 0; r < 1000; r++) {
                        long cur = dp[c][r];
                        if (cur == INF) continue;

                        // Pay exactly with current money (no extra 1000-yen note)
                        if (r >= price) {
                            int nr = r - price;
                            if (cur + price < ndp[c][nr]) {
                                ndp[c][nr] = cur + price;
                            }
                        }

                        // Add one 1000-yen note before purchase
                        int money = r + 1000;
                        if (money >= price) {
                            int change = money - price;
                            int gain = (change >= 500) ? 1 : 0;
                            int nr = change % 1000;
                            if (c + gain <= n && cur + 1000 < ndp[c + gain][nr]) {
                                ndp[c + gain][nr] = cur + 1000;
                            }
                        }
                    }
                }
                dp = ndp;
            }

            int bestCoins = -1;
            long minSpent = INF;
            for (int c = n; c >= 0; c--) {
                long best = INF;
                for (int r = 0; r < 1000; r++) {
                    best = Math.min(best, dp[c][r]);
                }
                if (best < INF) {
                    bestCoins = c;
                    minSpent = best;
                    break;
                }
            }

            out.append(bestCoins).append(' ').append(minSpent).append('\n');
        }

        System.out.print(out.toString());
    }
}
